import os
for f in sorted(os.listdir('DATA/products')):
    if f.endswith('.json'):
        d = json.load(open(f'DATA/products/{f}'))
        for u in d.get('urls', []):
            desc = u.get('description', '').lower()
            link = u.get('link', '').lower()
            if 'demo' in desc and ('competitor' in desc or 'competitor' in link or 'smart' in desc or 'tailor' in desc or 'persona' in desc):
                print(f, '|', u['link'], '|', u['description'])
        # Also check slack messages
        for msg in d.get('slack', []):
            text = msg.get('Message', {}).get('User', {}).get('text', '').lower()
            if 'competitor' in text and 'demo' in text:
                user = msg.get('Message', {}).get('User', {})
                print(f, '|', msg['id'], '|', user.get('userId'), '|', user.get('text','')[:200])
"

